def transform_general(grid):
    """Handle both horizontal and vertical separators"""
    h, w = len(grid), len(grid[0])

    # Check for horizontal separator (uniform row)
    for r in range(h):
        if len(set(grid[r])) == 1:
            # Section above separator
            section = grid[:r]
            counts = {}
            for row in section:
                for val in row:
                    if val != 0:
                        counts[val] = counts.get(val, 0) + 1
            pattern_value = max(counts, key=counts.get)
            result = [[2 if v == pattern_value else v for v in row] for row in section]
            return result

    # Check for vertical separator (uniform column)
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            # Section left of separator
            section = [row[:c] for row in grid]
            counts = {}
            for row in section:
                for val in row:
                    if val != 0:
                        counts[val] = counts.get(val, 0) + 1
            pattern_value = max(counts, key=counts.get)
            result = [[2 if v == pattern_value else v for v in row] for row in section]
            return result

    return grid

